const f = $input.first().json;

const projectName   = (f['Project Name']           || 'Story').trim();
const charDesc      = (f['Character Description']  || '').trim();
const rawScript     = (f['Script or Story Idea']   || '').trim();
const sceneJson     = (f['Pre-built Scene JSON']   || '').trim();
const genre         = (f['Genre and Tone']         || 'dark dramatic manhwa').trim();
const rawStyle      = (f['Art Style']              || '').trim();
const numScenes     = Math.max(1, parseInt(f['Number of Scenes']) || 8);
const groqKey       = (f['Groq API Key']           || '').trim() || '';
const aiStudioKey   = 'AIzaSyD5w08SOqdLeFCGnPlTOsucSQ_Rwn3wrWQ';

if (!charDesc)  throw new Error('Character Description is required.');
if (!rawScript && !sceneJson) throw new Error('Provide either a Script/Story OR Pre-built Scene JSON.');

const artStyle = rawStyle ||
  'manhwa webtoon korean comic style, clean precise linework, vibrant saturated colors, dramatic cinematic lighting, highly detailed digital illustration';

// Check Pre-built Scene JSON field first, then fall back to Script field
let preformattedScenes = null;
let isComplete = false;
let parsedProjectName = '';
let parsedSeed = null;
let parsedGenre = '';
let parsedStyle = '';
const jsonSource = sceneJson || rawScript;
try {
  const parsed = JSON.parse(jsonSource);
  if (Array.isArray(parsed)) {
    preformattedScenes = parsed;
  } else if (parsed && typeof parsed === 'object') {
    parsedProjectName = parsed.project_name || parsed.title || '';
    parsedSeed = parsed.consistency_seed || parsed.seed || null;
    parsedGenre = parsed.genre || '';
    parsedStyle = parsed.art_style || parsed.style || '';
    if (parsed.scenes && Array.isArray(parsed.scenes)) {
      preformattedScenes = parsed.scenes;
    } else {
      const arrayKey = Object.keys(parsed).find(key => Array.isArray(parsed[key]));
      if (arrayKey) preformattedScenes = parsed[arrayKey];
    }
  }
  if (preformattedScenes && preformattedScenes.length > 0) {
    const firstScene = preformattedScenes[0];
    isComplete = !!(firstScene.image_prompt || firstScene.video_prompt || firstScene.visual_prompt);
  }
} catch(e) {}

const finalNumScenes = preformattedScenes ? preformattedScenes.length : numScenes;
const seed = parsedSeed !== null && !isNaN(parseInt(parsedSeed)) ? parseInt(parsedSeed) : (Math.floor(Math.random() * 999999) + 1);
const maxTokens = Math.min(Math.max(finalNumScenes * 200, 4000), 32000);

const groqSystem =
  `You are a script supervisor. Read the script and identify exactly ${finalNumScenes} scene beats.\n` +
  `Output ONLY valid JSON - zero markdown, zero explanation:\n` +
  `{"scenes":[{"n":1,"beat":"1 sentence what happens","setting":"where + time","emotion":"one word"}]}`;

return [{
  json: {
    projectName: parsedProjectName || projectName,
    charDesc, rawScript,
    genre: parsedGenre || genre,
    artStyle: parsedStyle || artStyle,
    numScenes: finalNumScenes,
    groqKey, aiStudioKey, seed,
    isPreformatted: !!preformattedScenes,
    isComplete: isComplete,
    preformattedScenes: preformattedScenes,
    groqRequest: {
      model: 'gemini-2.5-flash',
      messages: [
        { role: 'system', content: groqSystem },
        { role: 'user',   content: `Identify ${finalNumScenes} scene beats:\n\n${rawScript}` }
      ],
      response_format: { type: 'json_object' },
      temperature: 0.3,
      max_tokens: maxTokens
    }
  }
}];

const resp   = $input.first().json;
const config = $('🔧 Prep + Build Groq Request').first().json;

if (config.isComplete || config.isPreformatted) {
  return [{
    json: {
      ...config,
      groqScenes: config.preformattedScenes,
      abliterateRequest: {
        model: 'huihui_ai/qwen2.5-abliterate:7b',
        messages: [{ role: 'user', content: 'dummy' }],
        options: { num_predict: 1 }
      }
    }
  }];
}

let groqScenes;
if (config.isPreformatted) {
  groqScenes = config.preformattedScenes;
} else {
  if (!resp.choices?.[0]?.message?.content) {
    throw new Error('Groq error: ' + JSON.stringify(resp).substring(0, 300));
  }
  const raw = resp.choices[0].message.content.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
  try { groqScenes = JSON.parse(raw).scenes; }
  catch {
    const m = raw.match(/\{[\s\S]*\}/);
    if (m) {
      try { groqScenes = JSON.parse(m[0]).scenes; }
      catch { throw new Error('Groq invalid JSON even after regex extraction. Length: ' + raw.length); }
    } else {
      throw new Error('Groq returned no JSON object. Length: ' + raw.length);
    }
  }
}

if (!Array.isArray(groqScenes) || !groqScenes.length) {
  throw new Error('Groq returned no scenes.');
}

const beatsList = groqScenes.map(s => `SCENE ${s.n || s.scene_number || 1}: ${s.beat || s.story_text || s.scene_text || 'Beat'}\n  Setting: ${s.setting || 'unknown'}\n  Emotion: ${s.emotion || 'dramatic'}`).join('\n\n');

const ablSystem =
  `You are an expert content architect specializing in high-retention short-form YouTube Shorts and Reels. Your single goal is to make every word, sentence, and scene maximally addictive with hyper-fast pacing.\n\nHOOK ARCHITECTURE: Open with a visceral question or bold claim. Drop micro-revelations and pattern interrupts every single sentence. No greetings, no warm-up. Start at the climax.\n\nPSYCHOLOGICAL TRIGGERS: Embed dopamine reward loops, high-stakes loss aversion, and intense curiosity gaps. Every scene must end on a mini cliffhanger to force them to watch the next one.\n\nTONE & PACING: Extremely fast-paced, aggressive, and punchy. Use short, rhythmic sentences. No filler words. If a sentence doesn\'t shock, escalate, or hook, CUT IT.\n\nCRITICAL CONSTRAINT: Each scene MUST be extremely short. 10 to 40 words MAXIMUM per scene. This equals 2 to 15 seconds of audio. Do not exceed this limit.\n\n` +
  `You are a master ${config.genre} manhwa writer. Write with full creative freedom - vivid, raw, emotional.\n\n` +
  `MAIN CHARACTER: ${config.charDesc}\n` +
  `GENRE: ${config.genre}\n\n` +
  `Task: Expand each scene beat into a VERY SHORT 20-40 word vivid description covering:\n` +
  ` What the reader SEES (composition, character pose, expression)\n` +
  ` What the character FEELS (internal state, physical sensation)\n` +
  ` ATMOSPHERE (lighting, weather, sounds)\n` +
  ` DIALOGUE (1-2 lines if natural)\n` +
  ` DRAMATIC TURNING POINT (what changes in this scene)\n\n` +
  `Label each: SCENE 1:\n[expansion]\n\nSCENE 2:\n[expansion]`;

return [{
  json: {
    ...config,
    groqScenes,
    abliterateRequest: {
      model: 'huihui_ai/qwen2.5-abliterate:7b',
      messages: [
        { role: 'system', content: ablSystem },
        { role: 'user',   content: `Expand these ${groqScenes.length} scene beats:\n\n${beatsList}` }
      ],
      stream: false,
      options: { temperature: 0.92, top_p: 0.95, num_ctx: 8192, num_predict: Math.min(groqScenes.length * 800, 8192), repeat_penalty: 1.1 }
    }
  }
}];

const resp   = $input.first().json;
const config = $('📊 Parse Groq → Build Abliterate').first().json;

if (config.isComplete || config.isPreformatted) {
  return [{
    json: {
      ...config,
      expandedText: '',
      coderRequest: {
        model: 'thirdeyeai/Qwen2.5-Coder-7B-Instruct-Uncensored:Q4_0',
        messages: [{ role: 'user', content: 'dummy' }],
        options: { num_predict: 1 }
      }
    }
  }];
}

const expandedText =
  resp.message?.content || resp.response ||
  (() => { throw new Error('Abliterate bad response: ' + JSON.stringify(resp).substring(0, 200)); })();

if (expandedText.trim().length < 200) {
  throw new Error('Abliterate returned too little — is the model loaded? Run: ollama run huihui_ai/qwen2.5-abliterate:7b');
}

const coderSystem =
  `You are a JSON architect. Convert story prose into structured JSON.\n` +
  `Output ONLY valid JSON — no markdown, no backticks, nothing else.\n\n` +
  `Required output:\n` +
  `{"scenes":[{\n` +
  `  "n": 1,\n` +
  `  "title": "Short punchy title max 5 words",\n` +
  `  "story_text": "3 sentence summary of what happens",\n` +
  `  "dialogue": "Most impactful line of dialogue or null",\n` +
  `  "setting": "Location time of day atmosphere",\n` +
  `  "emotion": "Primary emotion",\n` +
  `  "action": "Key physical action",\n` +
  `  "mood_tags": ["3 to 5 atmosphere tags"],\n` +
  `  "colors": ["3 dominant colors"]\n` +
  `}]}`;

return [{
  json: {
    ...config,
    expandedText,
    coderRequest: {
      model: 'thirdeyeai/Qwen2.5-Coder-7B-Instruct-Uncensored:Q4_0',
      messages: [
        { role: 'system', content: coderSystem },
        { role: 'user',   content: `Convert every scene in this text to JSON. Output ONLY the JSON object:\n\n${expandedText}` }
      ],
      stream: false,
      format: 'json',
      options: { temperature: 0.1, top_p: 0.85, num_ctx: 8192, num_predict: Math.min(expandedText.length, 8192) }
    }
  }
}];

const resp   = $input.first().json;
const config = $('📝 Parse Abliterate → Build Coder').first().json;

if (config.isComplete) {
  const normScenes = config.preformattedScenes.map((s, i) => ({
    n:          s.n || s.scene_number || (i + 1),
    title:      s.title || s.scene_title || `Scene ${i + 1}`,
    story_text: s.story_text || s.scene_text || '',
    dialogue:   s.dialogue !== undefined ? s.dialogue : null,
    setting:    s.setting    || 'unknown',
    emotion:    s.emotion    || s.primary_emotion || 'dramatic',
    action:     s.action     || s.action_beat || '',
    mood_tags:  Array.isArray(s.mood_tags) ? s.mood_tags : ['cinematic'],
    colors:     Array.isArray(s.colors) ? s.colors :
                Array.isArray(s.color_palette) ? s.color_palette : ['dark blue','gold','shadow'],
    image_prompt: s.image_prompt || null,
    negative_prompt: s.negative_prompt || null,
    video_prompt: s.video_prompt || null
  }));

  return [{
    json: {
      ...config,
      scenes: normScenes,
      openRouterRequest: {
        model:    config.orModel || 'mistralai/mistral-large',
        messages: [{ role: 'user', content: 'dummy' }],
        temperature: 0.1,
        max_tokens:  10
      }
    }
  }];
}

let scenes = [];
if (config.isPreformatted) {
  scenes = config.preformattedScenes;
} else {
  const rawText =
    resp.message?.content || resp.response ||
    (() => { throw new Error('Coder bad response: ' + JSON.stringify(resp).substring(0, 200)); })();

  const cleaned = rawText.replace(/```json\n?/gi,'').replace(/```\n?/g,'').trim();

  try {
    const p = JSON.parse(cleaned);
    scenes   = p.scenes || Object.values(p).find(v => Array.isArray(v)) || [];
  } catch {
    const m = cleaned.match(/\{[\s\S]*\}/);
    if (!m) throw new Error('No JSON in coder output: ' + cleaned.substring(0, 300));
    try {
      const p = JSON.parse(m[0]);
      scenes  = p.scenes || Object.values(p).find(v => Array.isArray(v)) || [];
    } catch { throw new Error('Invalid JSON from coder.'); }
  }
}

if (!scenes.length) throw new Error('No scenes found to parse.');

const normScenes = scenes.map((s, i) => ({
  n:          s.n || s.scene_number || (i + 1),
  title:      s.title      || `Scene ${i + 1}`,
  story_text: s.story_text || s.scene_text || '',
  dialogue:   s.dialogue !== undefined ? s.dialogue : null,
  setting:    s.setting    || 'unknown',
  emotion:    s.emotion    || s.primary_emotion || 'dramatic',
  action:     s.action     || s.action_beat || '',
  mood_tags:  Array.isArray(s.mood_tags) ? s.mood_tags : ['cinematic'],
  colors:     Array.isArray(s.colors) ? s.colors :
              Array.isArray(s.color_palette) ? s.color_palette : ['dark blue','gold','shadow'],
  image_prompt: s.image_prompt || null,
  negative_prompt: s.negative_prompt || null,
  video_prompt: s.video_prompt || null
}));

const orSystem =
  `You are a senior manhwa script editor. Polish scene descriptions and dialogue.\n` +
  `Return the SAME JSON structure — only improve story_text and dialogue.\n\n` +
  `IMPROVE:\n` +
  `• story_text → cinematic show-don't-tell, max 15-40 words total (1-2 punchy sentences). Must be very short for a 2-15 second video clip.\n` +
  `• dialogue → natural, subtext-rich, character-revealing. null if no dialogue fits.\n\n` +
  `DO NOT CHANGE: n, title, setting, emotion, action, mood_tags, colors\n` +
  `Character voice: ${config.charDesc}\n` +
  `Genre: ${config.genre}\n\n` +
  `Return ONLY JSON: {"scenes":[...]}`;

return [{
  json: {
    ...config,
    scenes: normScenes,
    openRouterRequest: {
      contents: [{
        role: 'user',
        parts: [{ text: `${orSystem}\n\nPolish story_text and dialogue:\n\n${JSON.stringify({scenes: normScenes}, null, 2)}` }]
      }],
      generationConfig: {
        temperature: 0.75,
        maxOutputTokens: Math.min(normScenes.length * 400, 32000),
        responseMimeType: 'application/json'
      }
    }
  }
}];

const resp   = $input.first().json;
const config = $('📋 Parse Coder → Build OpenRouter').first().json;

if (config.isComplete || config.isPreformatted) {
  return [{
    json: {
      ...config,
      polishedScenes: config.scenes,
      geminiRequest: {
        contents: [{
          role: 'user',
          parts: [{ text: 'dummy' }]
        }]
      }
    }
  }];
}

// Merge Gemini dialogue polish (fallback to Stage 3 scenes if it fails)
let polishedScenes = config.scenes;

// Try Gemini response format first, then OpenRouter format as fallback
const geminiText = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
const orText = resp.choices?.[0]?.message?.content || '';
const responseText = geminiText || orText;

if (responseText) {
  try {
    const raw = responseText
      .replace(/```json\n?/gi,'').replace(/```\n?/g,'').trim();
    const p   = JSON.parse(raw);
    const arr = p.scenes || Object.values(p).find(v => Array.isArray(v));
    if (Array.isArray(arr) && arr.length) {
      polishedScenes = config.scenes.map((scene, i) => {
        const polished = arr.find(s => (s.n === scene.n || s.scene_number === scene.n)) || arr[i];
        if (polished) {
          return {
            ...scene,
            story_text: polished.story_text || scene.story_text,
            dialogue:   polished.dialogue !== undefined ? polished.dialogue : scene.dialogue
          };
        }
        return scene;
      });
    }
  } catch { /* silent fallback */ }
}

// GEMINI AI STUDIO job: expert ComfyUI / AnythingXL prompt engineering
const geminiSystem =
  `VISUAL DIRECTION FOR ADDICTIVE CONTENT:\n- Faces and eyes in key frames — human gaze commands involuntary attention\n- Use contrast and unexpected juxtaposition to trigger pattern-interrupt responses\n- Every image must mirror the emotional beat — each image change is an emotional cue\n- Frame compositions that create visual tension: dutch angles for unease, low angles for power, extreme close-ups for intimacy\n- Color psychology: warm reds/golds for desire, cold blues for isolation, high contrast for danger\n- Characters should show raw emotion in their expressions — the audience must FEEL what the character feels\n- Dramatic lighting that creates mystery — half-lit faces, rim lighting, volumetric light shafts\n\n` +
  `You are an expert AI image prompt engineer for AnythingXL (Stable Diffusion XL).\n` +
  `Write optimized prompts for manhwa/webtoon style images.\n\n` +
  `For each scene output:\n` +
  `image_prompt — include ALL of these:\n` +
  `  • Quality tags: masterpiece, best quality, highly detailed, 8k\n` +
  `  • Character (ALWAYS): ${config.charDesc}\n` +
  `  • Art style: ${config.artStyle}\n` +
  `  • Specific camera angle (low angle / dutch tilt / overhead / close-up / etc)\n` +
  `  • Lighting setup (golden hour / harsh side light / rim light / neon glow / etc)\n` +
  `  • Color grading (warm tones / desaturated / high contrast / etc)\n` +
  `  • Narrative Literal: Explicitly describe EXACTLY what is happening in the scene based on the story text (who is doing what, specific actions, what objects are they interacting with). Do NOT just describe the mood.\n\n` +
  `video_prompt — 3 second motion description:\n` +
  `  • Camera: slow dolly push / tracking shot / slow zoom out / etc\n` +
  `  • Character action: specific movement\n` +
  `  • Environment: wind in hair / rain falling / dust particles / etc\n\n` +
  `negative_prompt — always:\n` +
  `worst quality, low quality, blurry, bad anatomy, deformed, ugly, watermark, text\n\n` +
  `Output ONLY JSON: {\"prompts\":[{\"n\":1,\"image_prompt\":\"...\",\"negative_prompt\":\"...\",\"video_prompt\":\"...\"}]}`;

const sceneSummary = polishedScenes.map(s =>
  `Scene ${s.n} — ${s.title}\nText: ${s.story_text}\nSetting: ${s.setting}\nEmotion: ${s.emotion}\nColors: ${s.colors.join(', ')}\nMood: ${s.mood_tags.join(', ')}`
).join('\n\n');

return [{
  json: {
    ...config,
    polishedScenes,
    geminiRequest: {
      contents: [{
        role: 'user',
        parts: [{ text: `Write AnythingXL image prompts for each scene. Output only JSON.\n\n${sceneSummary}` }]
      }],
      systemInstruction: { parts: [{ text: geminiSystem }] },
      generationConfig: {
        temperature: 0.6,
        maxOutputTokens: Math.min(polishedScenes.length * 800, 32000),
        responseMimeType: 'application/json'
      }
    }
  }
}];

const resp   = $input.first().json;
const config = $('🖼️ Parse OpenRouter → Build Gemini').first().json;

if (config.isComplete || config.isPreformatted) {
  const finalScenes = config.polishedScenes.map((scene, i) => {
    const original = (config.preformattedScenes && config.preformattedScenes[i]) || {};
    return {
      scene_number:  scene.n,
      scene_title:   scene.title,
      story_text:    scene.story_text,
      dialogue:      scene.dialogue || null,
      setting:       scene.setting,
      emotion:       scene.emotion,
      action:        scene.action,
      mood_tags:     scene.mood_tags,
      color_palette: scene.colors,
      image_prompt:  scene.image_prompt || original.image_prompt || '',
      negative_prompt: scene.negative_prompt || original.negative_prompt || '',
      video_prompt:  scene.video_prompt || original.video_prompt || '',
      width:  original.width || 1344,
      height: original.height || 768,
      steps:  original.steps || 30,
      cfg:    original.cfg || 7.5,
      seed:   original.seed || config.seed
    };
  });

  return [{
    json: {
      project_name:     config.projectName,
      title:            config.projectName,
      genre:            config.genre,
      art_style:        config.artStyle,
      char_desc:        config.charDesc,
      consistency_seed: config.seed,
      total_scenes:     finalScenes.length,
      models_used: {
        scene_breakdown: 'skipped (preformatted)',
        creative_expand: 'skipped (preformatted)',
        json_structure:  'skipped (preformatted)',
        dialogue_polish: 'skipped (preformatted)',
        image_prompts:   config.isComplete ? 'skipped (preformatted)' : 'skipped (preformatted — prompts needed)'
      },
      scenes: finalScenes,
      pipeline_options: {
        generate_images:    true,
        generate_video:     true,
        generate_tts:       true,
        use_ken_burns:      true,
        output_format:      'mp4',
        fps:                24,
        scene_duration_sec: 5
      }
    }
  }];
}

// Parse Gemini (AI Studio format)
let geminiPrompts = [];
try {
  const text    = resp.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const cleaned = text.replace(/```json\n?/gi,'').replace(/```\n?/g,'').trim();
  geminiPrompts = JSON.parse(cleaned).prompts || [];
} catch { /* fallback to generated prompts below */ }

// Merge all 5 stages into the final scene objects
const finalScenes = config.polishedScenes.map((scene, i) => {
  const gd = geminiPrompts.find(p => p.n === scene.n) || geminiPrompts[i] || {};
  const original = (config.preformattedScenes && config.preformattedScenes[i]) || {};

  return {
    scene_number:  scene.n,
    scene_title:   scene.title,
    story_text:    scene.story_text,
    dialogue:      scene.dialogue || null,
    setting:       scene.setting,
    emotion:       scene.emotion,
    action:        scene.action,
    mood_tags:     scene.mood_tags,
    color_palette: scene.colors,
    // Image gen — Gemini prompt or fallback
    image_prompt: gd.image_prompt ||
      `masterpiece, best quality, highly detailed, 8k, ${config.artStyle}, ${config.charDesc}, ${scene.setting}, ${scene.emotion} mood, cinematic lighting`,
    negative_prompt: gd.negative_prompt ||
      'worst quality, low quality, blurry, bad anatomy, deformed, ugly, watermark, text, cropped',
    video_prompt: gd.video_prompt ||
      `Slow cinematic push. ${config.charDesc}. ${scene.emotion}. ${config.artStyle}. 3 seconds.`,
    // ComfyUI params — prefer original preformatted values
    width:  original.width || 1344,
    height: original.height || 768,
    steps:  original.steps || 30,
    cfg:    original.cfg || 7.5,
    seed:   original.seed || config.seed
  };
});

return [{
  json: {
    project_name:     config.projectName,
    title:            config.projectName,
    genre:            config.genre,
    art_style:        config.artStyle,
    char_desc:        config.charDesc,
    consistency_seed: config.seed,
    total_scenes:     finalScenes.length,
    models_used: {
      scene_breakdown: 'gemini — gemini-2.5-flash',
      creative_expand: 'ollama — huihui_ai/qwen2.5-abliterate:7b',
      json_structure:  'ollama — Qwen2.5-Coder-7B-Uncensored',
      dialogue_polish: `openrouter — ${config.orModel}`,
      image_prompts:   'google — gemini-2.5-flash'
    },
    scenes: finalScenes,
    pipeline_options: {
      generate_images:    true,
      generate_video:     true,
      generate_tts:       true,
      use_ken_burns:      true,
      output_format:      'mp4',
      fps:                24,
      scene_duration_sec: 5
    }
  }
}];
